    rest: string;
    /** Header actions and other glyphs that recede until hovered. */
    iconQuiet: string;
    accent: string;
    accentSoft: string;
    onAccent: string;
    /** Running, connected, passing. */
    live: string;
    /** Waiting on the person, or at risk. */
    warn: string;
    danger: string;
    /** Commands and the names of things that run. */
    cmd: string;
    /** The mark of a host on the account. */
    host: string;
    /** An SSH host's mark. */
